export const QUOTES = [
  { id: "animo-001", category: "animo", text: "No necesitas resolver tu vida hoy; necesitas dar un paso que no te traicione." },
  { id: "animo-002", category: "animo", text: "La motivación más fiable aparece después de empezar, no antes." },
  { id: "animo-003", category: "animo", text: "Aunque avances lento, sigues estando del lado de quien no se rinde." },
  { id: "animo-004", category: "animo", text: "Hazlo con la energía que tengas; la constancia también acepta días imperfectos." },
  { id: "animo-005", category: "animo", text: "Un día modesto aún puede dejar un rincón de tu vida mejor de como lo encontró." },
  { id: "animo-006", category: "animo", text: "No esperes sentirte invencible para moverte; muévete para recordarte que puedes." },
  { id: "animo-007", category: "animo", text: "Tu siguiente intento no tiene que cargar con el peso de todos los anteriores." },
  { id: "animo-008", category: "animo", text: "Una acción honesta vence a una promesa brillante que nunca empieza." },
  { id: "animo-009", category: "animo", text: "Si hoy dudas de ti, haz algo tan claro que la duda tenga que apartarse." },
  { id: "animo-010", category: "animo", text: "El ánimo no siempre grita; a veces solo te susurra que sigas." },
  { id: "animo-011", category: "animo", text: "Hay días que no piden grandeza; piden presencia." },
  { id: "animo-012", category: "animo", text: "Vuelve a empezar con lo aprendido, sin convertir el regreso en un espectáculo." },
  { id: "animo-013", category: "animo", text: "Hoy no tienes que demostrarlo todo; solo no abandonarte." },
  { id: "animo-014", category: "animo", text: "Lo difícil pesa menos cuando lo partes en un gesto posible." },
  { id: "animo-015", category: "animo", text: "Tu progreso también merece respeto cuando nadie lo está mirando." },
  { id: "animo-016", category: "animo", text: "Empieza por la parte de ti que aún cree que hoy merece la pena intentarlo de nuevo." },
  { id: "animo-017", category: "animo", text: "Un paso cansado también puede acercarte a una vida que se parezca más a la tuya." },
  { id: "animo-018", category: "animo", text: "Puedes recuperar el impulso sin fingir que los días difíciles nunca ocurrieron." },
  { id: "animo-019", category: "animo", text: "Dale a esta mañana una oportunidad sincera antes de decidir cómo será el día entero." },
  { id: "animo-020", category: "animo", text: "La parte de ti que siguió adelante en silencio merece opinar sobre lo que viene ahora." },
  { id: "animo-021", category: "animo", text: "Termina hoy una tarea pequeña y date un motivo concreto para recuperar el ánimo." },
  { id: "animo-022", category: "animo", text: "Una etapa difícil puede cambiar tu ritmo sin quitarte la dirección." },
  { id: "animo-023", category: "animo", text: "Presentarte antes de que llegue la confianza también es una forma serena de valentía." },
  { id: "animo-024", category: "animo", text: "Haz que los próximos diez minutos sean más amables y conscientes que los anteriores." },
  { id: "animo-025", category: "animo", text: "No necesitas un regreso espectacular; por hoy basta con volver a ti en silencio." },
  { id: "animo-026", category: "animo", text: "Cumple hoy una promesa contigo y deja que sea la prueba de que el cambio ya ha empezado." },
  { id: "animo-027", category: "animo", text: "Lo que sigue inacabado no demuestra un fracaso; es simplemente donde puede empezar tu siguiente paso." },
  { id: "animo-028", category: "animo", text: "Hay fuerzas que solo regresan cuando dejas de exigir que vuelvan todas de golpe." },
  { id: "animo-029", category: "animo", text: "Elige la acción más pequeña que aligere mañana y dedícale toda tu atención." },
  { id: "animo-030", category: "animo", text: "Tu esperanza no tiene que hacer ruido; solo necesita espacio para influir en una decisión." },
  { id: "animo-031", category: "animo", text: "Una mañana difícil no se adueña de la tarde; elige algo útil y empieza por ahí." },
  { id: "animo-032", category: "animo", text: "Confía en el trabajo mientras sus primeros resultados aún sean demasiado pequeños para verse." },
  { id: "animo-033", category: "animo", text: "Cuando todo el camino pese, carga únicamente con el siguiente tramo." },
  { id: "animo-034", category: "animo", text: "El esfuerzo de hoy puede ser discreto y real; no necesita público para contar." },
  { id: "animo-035", category: "animo", text: "Una oportunidad perdida no es la última puerta; mira bien qué sigue abierto." },
  { id: "animo-036", category: "animo", text: "Reconoce el esfuerzo que hubo detrás de una decisión difícil, aunque nadie más viera lo que te costó." },
  { id: "animo-037", category: "animo", text: "Puedes cambiar el tono del día con un gesto amable hacia tu yo de mañana." },
  { id: "animo-038", category: "animo", text: "Si el plan se deshizo, conserva el propósito y elige una ruta más sencilla." },
  { id: "animo-039", category: "animo", text: "Lo que puedes ofrecer hoy sigue teniendo valor, aunque sea menos de lo que esperabas." },
  { id: "animo-040", category: "animo", text: "Cuando falte entusiasmo, pide a alguien de confianza que te acompañe durante la primera parte." },
  { id: "animo-041", category: "animo", text: "Tu esfuerzo no ha sido en vano solo porque la lección llegó antes que la recompensa." },
  { id: "animo-042", category: "animo", text: "Toma hoy una decisión que mañana te deje un poco más de espacio para respirar." },
  { id: "animo-043", category: "animo", text: "Volver a intentarlo puede parecer corriente desde fuera y aun así cambiar tu rumbo." },
  { id: "animo-044", category: "animo", text: "Ya has atravesado días inciertos; afronta este con los recursos que tienes ahora." },
  { id: "animo-045", category: "animo", text: "No esperes condiciones perfectas para cuidar de algo que de verdad te importa." },
  { id: "animo-046", category: "animo", text: "Un capítulo mejor puede empezar con una decisión tan pequeña que solo tú la notes." },
  { id: "animo-047", category: "animo", text: "Usa lo mucho que te importa como razón para actuar, no como otra razón para preocuparte." },
  { id: "animo-048", category: "animo", text: "Observa qué se ha vuelto más fácil este año; el esfuerzo de ayer quizá ya te ayude hoy." },
  { id: "animo-049", category: "animo", text: "Busca la parte del problema que responda a tus manos, tu voz o tu próxima llamada." },
  { id: "animo-050", category: "animo", text: "Lo que empiezas con dudas aún puede convertirse en algo que te alegre haber terminado." },
  { id: "animo-051", category: "animo", text: "Toma un resultado decepcionante como información y decide qué merece otro intento." },
  { id: "animo-052", category: "animo", text: "Empieza de una forma que encaje contigo hoy, no con la energía que esperabas tener." },
  { id: "animo-053", category: "animo", text: "Elige una tarea que puedas terminar y que tenga sentido suficiente para devolverte algo de confianza." },
  { id: "animo-054", category: "animo", text: "Un ajuste sincero puede mantener viva una meta mejor que aferrarte al plan original." },
  { id: "animo-055", category: "animo", text: "Envía la solicitud, haz la pregunta o abre el documento; deja que la realidad responda a la duda." },
  { id: "animo-056", category: "animo", text: "Una semana de decisiones discretas puede mostrar avances que un solo día no podría revelarte." },
  { id: "animo-057", category: "animo", text: "Acércate a la persona cuyo apoyo te ayuda a ver la situación con más claridad." },
  { id: "animo-058", category: "animo", text: "Cuando falte confianza, deja que la preparación sostenga parte del peso." },
  { id: "animo-059", category: "animo", text: "Ten paciencia con la parte de ti que aún aprende a manejar lo que viene después." },
  { id: "animo-060", category: "animo", text: "Antes de dar el día por perdido, haz algo que te facilite volver a ti." },
  { id: "foco-001", category: "foco", text: "El día cambia cuando decides qué no merece tu atención." },
  { id: "foco-002", category: "foco", text: "Una prioridad clara vale más que una lista enorme hecha con ansiedad." },
  { id: "foco-003", category: "foco", text: "Vuelve a lo que importa antes de que lo urgente te robe la mañana." },
  { id: "foco-004", category: "foco", text: "Cuando todas las tareas quieran ir primero, elige la que mañana echarías en falta." },
  { id: "foco-005", category: "foco", text: "Terminar una cosa pequeña puede ordenar más que abrir diez frentes nuevos." },
  { id: "foco-006", category: "foco", text: "Tu atención es una inversión: colócala donde quieras ver crecer algo." },
  { id: "foco-007", category: "foco", text: "Menos pestañas abiertas, menos ruido mental, más avance real." },
  { id: "foco-008", category: "foco", text: "No necesitas más horas; necesitas menos fugas." },
  { id: "foco-009", category: "foco", text: "Haz primero lo que te devuelve dirección, no lo que solo te da movimiento." },
  { id: "foco-010", category: "foco", text: "El foco no es tensión; es fidelidad a una cosa durante un rato." },
  { id: "foco-011", category: "foco", text: "Cuando digas sí a todo, tu objetivo escuchará un no." },
  { id: "foco-012", category: "foco", text: "Ponle borde al día: una tarea, un bloque, una decisión." },
  { id: "foco-013", category: "foco", text: "No confundas estar disponible con estar avanzando." },
  { id: "foco-014", category: "foco", text: "La claridad suele llegar después de quitar, no después de añadir." },
  { id: "foco-015", category: "foco", text: "Lo importante rara vez compite con ruido; espera a que tú lo elijas." },
  { id: "foco-016", category: "foco", text: "Protege la hora que puede cambiar tu día de los mensajes que solo vienen a interrumpirla." },
  { id: "foco-017", category: "foco", text: "Un no claro puede devolver más atención a tu vida que otro horario ingenioso." },
  { id: "foco-018", category: "foco", text: "Antes de añadir otra tarea, pregunta cuál de las pendientes sigue ocupando la habitación." },
  { id: "foco-019", category: "foco", text: "Deja suficiente silencio alrededor del trabajo para que entre tu mejor manera de pensar." },
  { id: "foco-020", category: "foco", text: "Decide qué significa avanzar durante esta hora, no durante toda tu vida." },
  { id: "foco-021", category: "foco", text: "La atención repartida entre cinco buenas ideas puede no terminar ninguna." },
  { id: "foco-022", category: "foco", text: "Programa la tarea importante cuando tengas más energía, no cuando quede mejor en el calendario." },
  { id: "foco-023", category: "foco", text: "Puedes responder después; la idea que tienes delante quizá no vuelva con la misma forma." },
  { id: "foco-024", category: "foco", text: "Una hora consciente puede proteger más de tu día que una docena vivida con prisa." },
  { id: "foco-025", category: "foco", text: "Deja que terminar, y no la novedad, decida hacia dónde va ahora tu atención." },
  { id: "foco-026", category: "foco", text: "La tarea se vuelve más clara cuando nombras el punto exacto en el que vas a parar." },
  { id: "foco-027", category: "foco", text: "Cierra la puerta a una distracción antes de pedirte una concentración más profunda." },
  { id: "foco-028", category: "foco", text: "Una lista corta y bien elegida puede contener más ambición que una lista abarrotada." },
  { id: "foco-029", category: "foco", text: "Cuando la mente se disperse, vuelve a la siguiente acción visible, no al plan entero." },
  { id: "foco-030", category: "foco", text: "Haz sitio para la profundidad rechazando una exigencia que nunca fue realmente tuya." },
  { id: "foco-031", category: "foco", text: "Anota el único resultado que haría útil esta hora y organiza el trabajo desde ahí." },
  { id: "foco-032", category: "foco", text: "Deja el teléfono fuera de alcance mientras la tarea necesite toda tu atención." },
  { id: "foco-033", category: "foco", text: "Elige el verbo de la tarea: escribir, llamar, comparar, decidir o borrar." },
  { id: "foco-034", category: "foco", text: "Ten una hoja cerca para las ideas sueltas y evita que se apoderen de la tarea presente." },
  { id: "foco-035", category: "foco", text: "Pon el archivo más relevante en el centro de la mesa y empieza por la evidencia más sólida." },
  { id: "foco-036", category: "foco", text: "Si no dejas de cambiar de tarea, detente y cierra primero el asunto pendiente más pequeño." },
  { id: "foco-037", category: "foco", text: "Lee dos veces el párrafo difícil antes de buscar una distracción más cómoda." },
  { id: "foco-038", category: "foco", text: "Si una idea pertenece a otro proyecto, archívala allí en vez de seguirla ahora." },
  { id: "foco-039", category: "foco", text: "Empieza por la pregunta que deberá responder el trabajo terminado." },
  { id: "foco-040", category: "foco", text: "Un temporizador puede marcar el límite mientras entregas toda tu atención al trabajo." },
  { id: "foco-041", category: "foco", text: "Cuando la tarea sea confusa, conviértela en una acción visible con un objeto concreto." },
  { id: "foco-042", category: "foco", text: "Comprueba si esa reunión te necesita antes de entregarle la mejor hora del día." },
  { id: "foco-043", category: "foco", text: "Deja a la vista el material de un solo proyecto y guarda todo lo demás." },
  { id: "foco-044", category: "foco", text: "Dedica menos tiempo a ordenar la lista y más tiempo a hacerla más corta." },
  { id: "foco-045", category: "foco", text: "Escribe la pregunta central arriba de la página para que cada detalle nuevo justifique su lugar." },
  { id: "foco-046", category: "foco", text: "Fija un punto final antes de que la perfección convierta una tarea en todo el día." },
  { id: "foco-047", category: "foco", text: "Si compiten dos prioridades, pregunta cuál facilita la otra o la vuelve innecesaria." },
  { id: "foco-048", category: "foco", text: "Concreta la siguiente acción hasta que tus manos sepan por dónde empezar." },
  { id: "foco-049", category: "foco", text: "Protege la mitad de la tarea; ahí suele acabarse la novedad y empezar el trabajo útil." },
  { id: "foco-050", category: "foco", text: "Antes de abrir otra fuente, explica qué dice realmente la información que ya tienes." },
  { id: "foco-051", category: "foco", text: "Reserva un momento breve para responder y evita que los mensajes dividan todas tus horas." },
  { id: "foco-052", category: "foco", text: "Si pierdes el hilo, relee la última decisión en vez de reiniciar el plan completo." },
  { id: "foco-053", category: "foco", text: "Una puerta cerrada, una mesa despejada y un objetivo claro pueden bastar para trabajar bien." },
  { id: "foco-054", category: "foco", text: "Usa tus notas para retomar rápido, no para aplazar la parte difícil de pensar." },
  { id: "foco-055", category: "foco", text: "Decide qué detalle afecta al resultado y permite que los decorativos queden sin pulir." },
  { id: "foco-056", category: "foco", text: "Trabaja en el orden que exige el problema, no en el que sugieren las partes fáciles." },
  { id: "foco-057", category: "foco", text: "Desactiva una alerta y observa cuánto más puede acompañarte un pensamiento completo." },
  { id: "foco-058", category: "foco", text: "Un borrador útil responde primero a la pregunta principal y después mejora cada frase." },
  { id: "foco-059", category: "foco", text: "Nombra la interrupción, déjala por escrito y vuelve a la línea exacta donde estabas." },
  { id: "foco-060", category: "foco", text: "Termina la sesión anotando el siguiente paso, para que mañana empiece con rumbo y no con memoria." },
  { id: "calma-001", category: "calma", text: "Respira antes de responder; a veces la paz cabe en tres segundos." },
  { id: "calma-002", category: "calma", text: "No todo lo que sientes necesita una reacción inmediata." },
  { id: "calma-003", category: "calma", text: "Baja el volumen del día hasta poder escucharte otra vez." },
  { id: "calma-004", category: "calma", text: "Un ritmo más lento puede mostrarte la parte del día que tu prisa dejaba atrás." },
  { id: "calma-005", category: "calma", text: "Tu cuerpo no es un obstáculo; es el lugar desde el que vives." },
  { id: "calma-006", category: "calma", text: "Suelta por un momento lo que no puedes arreglar desde este minuto." },
  { id: "calma-007", category: "calma", text: "Una pausa breve puede protegerte de una decisión tomada desde el cansancio." },
  { id: "calma-008", category: "calma", text: "La calma no siempre llega sola; a veces hay que prepararle sitio." },
  { id: "calma-009", category: "calma", text: "No necesitas ganar la discusión con tu mente; puedes dejarla pasar." },
  { id: "calma-010", category: "calma", text: "Hoy también puedes elegir suavidad sin perder firmeza." },
  { id: "calma-011", category: "calma", text: "Lo que pesa mucho se mira mejor sentado, respirando y sin prisa." },
  { id: "calma-012", category: "calma", text: "No confundas silencio con vacío; a veces es reparación." },
  { id: "calma-013", category: "calma", text: "Si no puedes con todo, empieza por volver a tu respiración." },
  { id: "calma-014", category: "calma", text: "La serenidad no niega el problema; evita que el problema te gobierne." },
  { id: "calma-015", category: "calma", text: "Date permiso para no acelerar cuando tu vida pide cuidado." },
  { id: "calma-016", category: "calma", text: "Deja que tus hombros entiendan que nada tiene que resolverse durante esta respiración." },
  { id: "calma-017", category: "calma", text: "Puedes esperar a que la emoción se asiente antes de decidir qué significa." },
  { id: "calma-018", category: "calma", text: "Retira una cosa de tu mesa interior; no necesitas sostener todas las preocupaciones a la vez." },
  { id: "calma-019", category: "calma", text: "Una respuesta más lenta puede cuidar la verdad y también a quien necesita escucharla." },
  { id: "calma-020", category: "calma", text: "Observa lo que permanece: el suelo, la silla, el aire que llega sin instrucciones." },
  { id: "calma-021", category: "calma", text: "Ponle un límite al ruido en lugar de exigirte que hables más fuerte que él." },
  { id: "calma-022", category: "calma", text: "El día puede quedarse inacabado mientras te tomas un momento para volver a estar presente." },
  { id: "calma-023", category: "calma", text: "No todo pensamiento inquieto merece una silla en el centro de la habitación." },
  { id: "calma-024", category: "calma", text: "Apoya la atención en algo cotidiano hasta que tu mente deje de correr por delante." },
  { id: "calma-025", category: "calma", text: "No te estás quedando atrás por detenerte lo suficiente para elegir bien el siguiente paso." },
  { id: "calma-026", category: "calma", text: "Suelta esa versión de la conversación que solo ha ocurrido dentro de tu imaginación." },
  { id: "calma-027", category: "calma", text: "No hace falta convertir un minuto difícil en una predicción sobre toda la semana." },
  { id: "calma-028", category: "calma", text: "Deja que la quietud sea un lugar para recogerte, no otra meta que debas cumplir." },
  { id: "calma-029", category: "calma", text: "Antes de buscar otra explicación, observa un detalle estable y tranquilizador a tu alrededor." },
  { id: "calma-030", category: "calma", text: "Haz este momento más pequeño: esta habitación, este aire y una sola cosa que puedas hacer con calma." },
  { id: "calma-031", category: "calma", text: "Nombra tres cosas que hoy sean ciertas antes de dar más espacio a todo lo incierto." },
  { id: "calma-032", category: "calma", text: "Espera a que tu voz se serene antes de responder una pregunta importante." },
  { id: "calma-033", category: "calma", text: "Abre la ventana, nota la temperatura y vuelve al día que de verdad estás viviendo." },
  { id: "calma-034", category: "calma", text: "Escucha un sonido cotidiano hasta que la prisa empiece a aflojar." },
  { id: "calma-035", category: "calma", text: "Una preocupación escrita ya no necesita dar vueltas en tu mente para ser recordada." },
  { id: "calma-036", category: "calma", text: "Puedes dejar la respuesta para mañana y devolverle a la noche su silencio." },
  { id: "calma-037", category: "calma", text: "Afloja las manos; no tienen que cargar con un problema que pertenece a mañana." },
  { id: "calma-038", category: "calma", text: "Busca un lugar más tranquilo antes de exigirle silencio a tu mente." },
  { id: "calma-039", category: "calma", text: "El agua caliente, la ropa limpia y una cena sin prisa pueden hacer más amable la noche." },
  { id: "calma-040", category: "calma", text: "No saberlo todavía resulta incómodo, pero no exige una conclusión apresurada." },
  { id: "calma-041", category: "calma", text: "Baja la luz y el ritmo; el día no necesita terminar a todo volumen." },
  { id: "calma-042", category: "calma", text: "Ponle nombre a lo que sientes sin convertirlo en una orden." },
  { id: "calma-043", category: "calma", text: "Toma el camino largo a casa si esos minutos te ayudan a llegar con la mente más despejada." },
  { id: "calma-044", category: "calma", text: "La conversación puede esperar hasta que puedas escuchar algo más que tu propia urgencia." },
  { id: "calma-045", category: "calma", text: "Observa cinco cosas que no te estén pidiendo nada en este momento." },
  { id: "calma-046", category: "calma", text: "Usa una rutina sencilla para indicarle a tu mente que el trabajo ha terminado por hoy." },
  { id: "calma-047", category: "calma", text: "Quizá entiendas mejor la situación después de comer, descansar y tomar algo de distancia." },
  { id: "calma-048", category: "calma", text: "Lee el mensaje una vez y deja el teléfono antes de imaginar todo lo que podría significar." },
  { id: "calma-049", category: "calma", text: "Deja espacio entre lo ocurrido y la historia que estás a punto de construir a su alrededor." },
  { id: "calma-050", category: "calma", text: "Espera a que hierva el agua sin llenar ese minuto con otra exigencia." },
  { id: "calma-051", category: "calma", text: "Unos minutos sin estímulos pueden ayudarte a notar lo que ya estaba dentro del día." },
  { id: "calma-052", category: "calma", text: "Muévete al ritmo que te permita notar dónde estás colocando la atención." },
  { id: "calma-053", category: "calma", text: "Dobla una prenda o lava una taza y deja que esa acción sencilla baje el ritmo del momento." },
  { id: "calma-054", category: "calma", text: "Pregúntate si este pensamiento necesita atención ahora, más tarde o si no la necesita." },
  { id: "calma-055", category: "calma", text: "Permite que termine la música antes de decidir con qué llenar el próximo silencio." },
  { id: "calma-056", category: "calma", text: "Sal un minuto y permite que el horizonte ocupe más espacio que la pantalla." },
  { id: "calma-057", category: "calma", text: "Un horario más amable empieza al admitir cuánto puede contener el día de forma razonable." },
  { id: "calma-058", category: "calma", text: "Deja el problema a un lado un rato; cargar con él a todas horas no equivale a resolverlo." },
  { id: "calma-059", category: "calma", text: "La próxima hora no necesita un plan perfecto, sino un ritmo en el que puedas estar." },
  { id: "calma-060", category: "calma", text: "Termina el sorbo antes de buscar la siguiente tarea; este minuto puede seguir siendo sencillo." },
  { id: "disciplina-001", category: "disciplina", text: "La disciplina es hacerle caso a tu futuro cuando tu presente negocia." },
  { id: "disciplina-002", category: "disciplina", text: "No necesitas ganas constantes; necesitas un acuerdo contigo." },
  { id: "disciplina-003", category: "disciplina", text: "Hazlo pequeño, pero hazlo hoy: así se entrena la confianza." },
  { id: "disciplina-004", category: "disciplina", text: "La promesa que cumples en silencio cambia más que la que anuncias." },
  { id: "disciplina-005", category: "disciplina", text: "Repetir el paso útil en días corrientes da a un proyecto largo una base estable sobre la que avanzar." },
  { id: "disciplina-006", category: "disciplina", text: "Si esperas el momento perfecto, le entregas el mando a la excusa." },
  { id: "disciplina-007", category: "disciplina", text: "La disciplina no te encierra; te libera de empezar siempre desde cero." },
  { id: "disciplina-008", category: "disciplina", text: "Un mínimo bien cumplido vale más que un plan enorme abandonado." },
  { id: "disciplina-009", category: "disciplina", text: "Hoy no negocies con la parte de ti que siempre aplaza." },
  { id: "disciplina-010", category: "disciplina", text: "La constancia es una forma discreta de respeto propio." },
  { id: "disciplina-011", category: "disciplina", text: "Cumple lo básico incluso cuando nadie pueda aplaudirlo." },
  { id: "disciplina-012", category: "disciplina", text: "La repetición convierte una intención en algo que puedes revisar y mejorar." },
  { id: "disciplina-013", category: "disciplina", text: "Completa el primer paso acordado antes de decidir si el plan necesita cambiar." },
  { id: "disciplina-014", category: "disciplina", text: "No busques intensidad diaria; busca una base que no se rompa." },
  { id: "disciplina-015", category: "disciplina", text: "Cada promesa cumplida hace que el próximo comienzo resulte un poco menos extraño." },
  { id: "disciplina-016", category: "disciplina", text: "Construye una rutina que también funcione cuando el entusiasmo esté en otra parte." },
  { id: "disciplina-017", category: "disciplina", text: "El plan útil es el que puedes seguir un miércoles cualquiera." },
  { id: "disciplina-018", category: "disciplina", text: "Mantén cerca la línea de salida para que las excusas no puedan esconderte el camino." },
  { id: "disciplina-019", category: "disciplina", text: "Haz la cantidad acordada y para con la satisfacción de haber cumplido tu palabra." },
  { id: "disciplina-020", category: "disciplina", text: "Poner límites al esfuerzo evita que el compromiso termine convertido en castigo." },
  { id: "disciplina-021", category: "disciplina", text: "Prepara esta noche la primera acción para que mañana quede menos espacio para negociar." },
  { id: "disciplina-022", category: "disciplina", text: "Mide el regreso, no la interrupción; volver es la habilidad que estás construyendo." },
  { id: "disciplina-023", category: "disciplina", text: "Elige un mínimo que proteja la continuidad sin fingir que todos los días son iguales." },
  { id: "disciplina-024", category: "disciplina", text: "Haz que el calendario refleje tu compromiso antes de que tu ánimo pueda votar." },
  { id: "disciplina-025", category: "disciplina", text: "Déjate una prueba visible: una repetición terminada y registrada con honestidad." },
  { id: "disciplina-026", category: "disciplina", text: "Un ritmo fiable puede parecer poco impresionante mientras te lleva hacia delante." },
  { id: "disciplina-027", category: "disciplina", text: "Quita una decisión de la rutina y reserva el esfuerzo para hacer el trabajo." },
  { id: "disciplina-028", category: "disciplina", text: "No obligues a mañana a pagar todo lo que aplazaste hoy; empieza por una tarea sincera." },
  { id: "disciplina-029", category: "disciplina", text: "La constancia crece cuando la promesa es tan concreta que sabes cuándo está cumplida." },
  { id: "disciplina-030", category: "disciplina", text: "Respeta la estructura que te ayuda a actuar y ajústala cuando la vida cambie de verdad." },
  { id: "disciplina-031", category: "disciplina", text: "Pon al trabajo un plazo visible antes de que se extienda por todas las horas disponibles." },
  { id: "disciplina-032", category: "disciplina", text: "Decide qué días son para practicar y protege ese tiempo de recados opcionales." },
  { id: "disciplina-033", category: "disciplina", text: "Empieza a la hora acordada, aunque los primeros diez minutos no sean brillantes." },
  { id: "disciplina-034", category: "disciplina", text: "Cuida la cita con tu propio trabajo igual que cuidarías una cita con otra persona." },
  { id: "disciplina-035", category: "disciplina", text: "Registra lo que terminaste, no las promesas grandiosas que hiciste al principio." },
  { id: "disciplina-036", category: "disciplina", text: "Cuando un método falle repetidamente, cambia el método y conserva la cita." },
  { id: "disciplina-037", category: "disciplina", text: "Decide cuánto durará la sesión y usa ese límite para trabajar con intención." },
  { id: "disciplina-038", category: "disciplina", text: "Facilita la decisión útil antes de pedirle a la fuerza de voluntad que salve la tarde." },
  { id: "disciplina-039", category: "disciplina", text: "Termina la cantidad prevista antes de decidir si te sientes productivo." },
  { id: "disciplina-040", category: "disciplina", text: "Usa una lista para lo rutinario y reserva tu criterio para las decisiones que lo necesitan." },
  { id: "disciplina-041", category: "disciplina", text: "Elige un ritmo semanal que deje espacio tanto para el esfuerzo como para la recuperación." },
  { id: "disciplina-042", category: "disciplina", text: "Si pierdes la mañana, aprovecha la tarde en vez de esperar un reinicio más limpio." },
  { id: "disciplina-043", category: "disciplina", text: "Deja listo el lugar de trabajo para que mañana empezar exija menos persuasión." },
  { id: "disciplina-044", category: "disciplina", text: "Un registro sincero de tres repeticiones vale más que una racha perfecta que no puedes sostener." },
  { id: "disciplina-045", category: "disciplina", text: "Define qué significa terminar antes de empezar, para que la dificultad no mueva la meta." },
  { id: "disciplina-046", category: "disciplina", text: "Reduce la tarea hasta que la resistencia pierda sus argumentos y termina esa versión." },
  { id: "disciplina-047", category: "disciplina", text: "Practica por separado el paso difícil hasta que deje de frenar toda la rutina." },
  { id: "disciplina-048", category: "disciplina", text: "Detente en el punto previsto; la disciplina también consiste en no convertir el esfuerzo en exceso." },
  { id: "disciplina-049", category: "disciplina", text: "Evalúa el proceso al terminar la semana, no después de cada hora incómoda." },
  { id: "disciplina-050", category: "disciplina", text: "Pon la tarea recurrente en el calendario antes de que el hueco se llene solo." },
  { id: "disciplina-051", category: "disciplina", text: "Haz la preparación poco vistosa que permitirá el trabajo importante de mañana." },
  { id: "disciplina-052", category: "disciplina", text: "Completa la tarea de mantenimiento antes de que el descuido la convierta en la urgencia de mañana." },
  { id: "disciplina-053", category: "disciplina", text: "Elige herramientas que hagan evidente la acción correcta cuando tu atención esté cansada." },
  { id: "disciplina-054", category: "disciplina", text: "Una meta modesta, cumplida con regularidad, puede sostener una gran ambición sin consumir tu vida." },
  { id: "disciplina-055", category: "disciplina", text: "Elimina los pasos de más que ofrecen nuevos escondites a la procrastinación." },
  { id: "disciplina-056", category: "disciplina", text: "Revisa el compromiso si cambian tus circunstancias, no solo cuando el trabajo resulte aburrido." },
  { id: "disciplina-057", category: "disciplina", text: "Completa la parte de hoy antes de tomar prestada la energía reservada para descansar." },
  { id: "disciplina-058", category: "disciplina", text: "Si el sistema falla una y otra vez, mejora la preparación en vez de aumentar el castigo." },
  { id: "disciplina-059", category: "disciplina", text: "Conserva una rutina fiable durante una semana caótica y deja que lo demás sea opcional." },
  { id: "disciplina-060", category: "disciplina", text: "Cierra el día preparando algo que mañana te permita empezar de forma más directa." },
  { id: "autoestima-001", category: "autoestima", text: "Háblate como si tuvieras que convivir contigo toda la vida, porque es verdad." },
  { id: "autoestima-002", category: "autoestima", text: "Tu valor no sube ni baja con la opinión más reciente." },
  { id: "autoestima-003", category: "autoestima", text: "No eres un proyecto pendiente; eres una persona en proceso." },
  { id: "autoestima-004", category: "autoestima", text: "Tratarte con dureza no te ayuda a mejorar más rápido; solo te desgasta." },
  { id: "autoestima-005", category: "autoestima", text: "Puedes reconocer lo que falta sin negar todo lo que ya eres." },
  { id: "autoestima-006", category: "autoestima", text: "No necesitas convertirte en otra persona para merecer cuidado." },
  { id: "autoestima-007", category: "autoestima", text: "La comparación reduce una vida completa a una foto ajena." },
  { id: "autoestima-008", category: "autoestima", text: "Tu descanso no tiene que justificarse con agotamiento extremo." },
  { id: "autoestima-009", category: "autoestima", text: "No todo error merece castigo; algunos solo piden aprendizaje." },
  { id: "autoestima-010", category: "autoestima", text: "Sé leal a ti también cuando estés decepcionado contigo." },
  { id: "autoestima-011", category: "autoestima", text: "No te abandones para encajar en un lugar que no te cuida." },
  { id: "autoestima-012", category: "autoestima", text: "Toma hoy una decisión en la que tu propia voz no sea la última en ser consultada." },
  { id: "autoestima-013", category: "autoestima", text: "Tu sensibilidad puede ofrecer información útil; escúchala sin dejar que una sola emoción lo decida todo." },
  { id: "autoestima-014", category: "autoestima", text: "Deja de pedirte perfección para concederte cariño." },
  { id: "autoestima-015", category: "autoestima", text: "Eres más que tu productividad, incluso en tus mejores días." },
  { id: "autoestima-016", category: "autoestima", text: "Puedes corregir el rumbo sin convertirte en tu propio enemigo." },
  { id: "autoestima-017", category: "autoestima", text: "Haz de tu voz interior un lugar donde mirar los errores sin humillarte." },
  { id: "autoestima-018", category: "autoestima", text: "Las cualidades que admiras en otros no demuestran que tú carezcas de ellas." },
  { id: "autoestima-019", category: "autoestima", text: "No le debes a nadie una versión reducida de ti para que la habitación resulte más cómoda." },
  { id: "autoestima-020", category: "autoestima", text: "Tus necesidades siguen siendo reales aunque no sepas explicarlas a la perfección." },
  { id: "autoestima-021", category: "autoestima", text: "Observa de quién son las exigencias antes de decidir que tú no eres suficiente." },
  { id: "autoestima-022", category: "autoestima", text: "Puedes sentir orgullo por cómo afrontaste algo y aun desear que hubiera sido distinto." },
  { id: "autoestima-023", category: "autoestima", text: "Ofrécete la paciencia que darías sin pensar a quien aprende algo difícil." },
  { id: "autoestima-024", category: "autoestima", text: "Un límite no significa que te importe menos; a veces demuestra que también cuentas contigo." },
  { id: "autoestima-025", category: "autoestima", text: "No dejes que tu hora más insegura sea la encargada de definir todo tu carácter." },
  { id: "autoestima-026", category: "autoestima", text: "Puedes disfrutar de lo que has construido antes de decidir cómo mejorarlo." },
  { id: "autoestima-027", category: "autoestima", text: "Trata tus límites como información, no como un veredicto sobre tu valor." },
  { id: "autoestima-028", category: "autoestima", text: "Observa qué lugares te permiten hablar con libertad sin convertir tu dignidad en una disculpa." },
  { id: "autoestima-029", category: "autoestima", text: "Di una verdad sobre ti que no tenga ninguna relación con tus logros." },
  { id: "autoestima-030", category: "autoestima", text: "Puedes superar un juicio antiguo sin demostrar que quien lo hizo estaba equivocado." },
  { id: "autoestima-031", category: "autoestima", text: "Guarda un pequeño registro de lo que resolviste bien; la duda rara vez conserva un archivo fiel." },
  { id: "autoestima-032", category: "autoestima", text: "Deja que un cumplido llegue sin explicar enseguida por qué quizá no lo mereces." },
  { id: "autoestima-033", category: "autoestima", text: "Tus bordes inacabados no anulan las partes de ti que ya se sienten firmes." },
  { id: "autoestima-034", category: "autoestima", text: "Elige ropa, planes y compañía que te permitan habitar tu vida sin interpretar un papel." },
  { id: "autoestima-035", category: "autoestima", text: "Detecta cuándo corregirte se convierte en atacarte y detén ahí la conversación." },
  { id: "autoestima-036", category: "autoestima", text: "Un momento incómodo es muy poca prueba para reescribir toda la opinión que tienes de ti." },
  { id: "autoestima-037", category: "autoestima", text: "Deja que tus preferencias existan antes de preguntar si los demás las aprueban." },
  { id: "autoestima-038", category: "autoestima", text: "El cuidado que ofreces a otros también es una habilidad que puedes practicar contigo." },
  { id: "autoestima-039", category: "autoestima", text: "Discúlpate por el daño que causaste, no por el espacio que ocupa tu presencia honesta." },
  { id: "autoestima-040", category: "autoestima", text: "Una respuesta más lenta puede respetarte más que un sí inmediato que no deseabas dar." },
  { id: "autoestima-041", category: "autoestima", text: "Lee tus antiguos planes con cariño; se escribieron con la información que tenías entonces." },
  { id: "autoestima-042", category: "autoestima", text: "Toma hoy una decisión porque encaja contigo, no porque sea fácil de explicar." },
  { id: "autoestima-043", category: "autoestima", text: "Puedes ser principiante sin convertir la falta de experiencia en un defecto personal." },
  { id: "autoestima-044", category: "autoestima", text: "Separa lo que necesita mejorar de lo que simplemente no agrada a una persona concreta." },
  { id: "autoestima-045", category: "autoestima", text: "Protege tiempo para ti con el mismo cuidado que dedicas al trabajo que depende de ti." },
  { id: "autoestima-046", category: "autoestima", text: "Permite que una foto tuya sea un recuerdo y no una inspección." },
  { id: "autoestima-047", category: "autoestima", text: "Cuando cambias de opinión con criterio, respondes a la vida en vez de traicionarte." },
  { id: "autoestima-048", category: "autoestima", text: "No dejes que la urgencia ajena decida cuánto de ti tienes que entregar." },
  { id: "autoestima-049", category: "autoestima", text: "No hay premio por ser la última persona en notar que necesitas amabilidad." },
  { id: "autoestima-050", category: "autoestima", text: "Disfruta de un placer cotidiano sin exigir productividad como precio de entrada." },
  { id: "autoestima-051", category: "autoestima", text: "Un no sincero puede proteger la parte de ti que un sí automático sigue ignorando." },
  { id: "autoestima-052", category: "autoestima", text: "Habla de tus fortalezas con la misma precisión con la que enumeras tus defectos." },
  { id: "autoestima-053", category: "autoestima", text: "Puedes echar de menos quien eras sin tratar como una decepción a quien eres ahora." },
  { id: "autoestima-054", category: "autoestima", text: "Un día dedicado a conocer tus límites también puede ser un día bien aprovechado." },
  { id: "autoestima-055", category: "autoestima", text: "Pregúntate si la regla que rompiste era justa antes de usarla como prueba contra ti." },
  { id: "autoestima-056", category: "autoestima", text: "Deja que tu cuerpo sea un lugar que habitas con atención, no un problema que vigilas todo el día." },
  { id: "autoestima-057", category: "autoestima", text: "Recibir ayuda no borra el esfuerzo que hiciste antes de que alguien llegara." },
  { id: "autoestima-058", category: "autoestima", text: "La persona en la que te conviertes necesita ánimo tanto como comentarios sinceros." },
  { id: "autoestima-059", category: "autoestima", text: "Protege un poco de intimidad; no toda parte valiosa de ti necesita público." },
  { id: "autoestima-060", category: "autoestima", text: "Termina una crítica hacia ti nombrando en su lugar la siguiente acción útil." },
  { id: "gratitud-001", category: "gratitud", text: "Agradecer no niega lo difícil; recuerda que no todo está perdido." },
  { id: "gratitud-002", category: "gratitud", text: "Hay días que se salvan al notar una sola cosa buena con atención." },
  { id: "gratitud-003", category: "gratitud", text: "Lo cotidiano también merece ceremonia: agua, luz, techo, alguien que responde." },
  { id: "gratitud-004", category: "gratitud", text: "La gratitud convierte lo suficiente en algo visible." },
  { id: "gratitud-005", category: "gratitud", text: "Mira lo que ya te sostiene antes de perseguir lo que falta." },
  { id: "gratitud-006", category: "gratitud", text: "Algunos regalos parecen una tarde tranquila en la que tu cuerpo por fin se siente seguro." },
  { id: "gratitud-007", category: "gratitud", text: "A veces la abundancia empieza cuando dejas de mirar solo la carencia." },
  { id: "gratitud-008", category: "gratitud", text: "Hoy agradece algo que antes pedías en silencio." },
  { id: "gratitud-009", category: "gratitud", text: "La vida no tiene que ser perfecta para tener partes preciosas." },
  { id: "gratitud-010", category: "gratitud", text: "Cuando observas los pequeños consuelos, el día gana detalles que la prisa habría pasado por alto." },
  { id: "gratitud-011", category: "gratitud", text: "Hay estabilidad en cosas simples que casi nunca celebras." },
  { id: "gratitud-012", category: "gratitud", text: "Agradecer también es detenerse lo suficiente para recibir." },
  { id: "gratitud-013", category: "gratitud", text: "No esperes al gran logro para reconocer la belleza del camino." },
  { id: "gratitud-014", category: "gratitud", text: "Lo que hoy parece normal quizá fue un sueño en otro momento." },
  { id: "gratitud-015", category: "gratitud", text: "La gratitud no cambia todos los hechos, pero cambia desde dónde los miras." },
  { id: "gratitud-016", category: "gratitud", text: "Observa los apoyos silenciosos que sostienen tu día antes de llamarlo corriente." },
  { id: "gratitud-017", category: "gratitud", text: "Agradece a la versión de ti que hizo esa pequeña tarea que ahora das por sentada." },
  { id: "gratitud-018", category: "gratitud", text: "Hay cosas buenas que pasan inadvertidas porque llegan con fidelidad y no con espectáculo." },
  { id: "gratitud-019", category: "gratitud", text: "Vuelve a mirar un consuelo conocido: agua caliente, sábanas limpias, una ventana abierta." },
  { id: "gratitud-020", category: "gratitud", text: "La gratitud puede sentarse junto a la decepción; ninguna tiene que borrar a la otra." },
  { id: "gratitud-021", category: "gratitud", text: "Recuerda una amabilidad que cambió la temperatura de un día que venía siendo difícil." },
  { id: "gratitud-022", category: "gratitud", text: "Lo que te sostiene en silencio quizá merezca más atención que lo que te impresiona un momento." },
  { id: "gratitud-023", category: "gratitud", text: "Recibe el buen momento sin pedirle que justifique todo lo ocurrido antes." },
  { id: "gratitud-024", category: "gratitud", text: "Un nombre, una comida, un mensaje, un regreso seguro: deja que algo concreto baste para sentir gratitud." },
  { id: "gratitud-025", category: "gratitud", text: "Observa lo que ya no duele como antes; la recuperación también puede volverse cotidiana." },
  { id: "gratitud-026", category: "gratitud", text: "La vida que deseas no está solo delante; quizá algunas partes ya estén en esta habitación." },
  { id: "gratitud-027", category: "gratitud", text: "Da las gracias mientras ocurre el momento cotidiano, no solo cuando se convierta en recuerdo." },
  { id: "gratitud-028", category: "gratitud", text: "Nombra exactamente qué hizo este momento más amable; la gratitud se aclara en los detalles." },
  { id: "gratitud-029", category: "gratitud", text: "Alguien te hizo sitio una vez; lleva esa calidez al espacio que tú ofreces a los demás." },
  { id: "gratitud-030", category: "gratitud", text: "Termina el día encontrando algo que no te pidió nada y aun así te dio consuelo." },
  { id: "gratitud-031", category: "gratitud", text: "Fíjate en quien aligera una tarea cotidiana simplemente cumpliendo con su parte." },
  { id: "gratitud-032", category: "gratitud", text: "Antes de recoger la mesa, recuerda algo que se haya compartido alrededor de ella." },
  { id: "gratitud-033", category: "gratitud", text: "Una llave que abre, un móvil cargado, una ruta conocida: la utilidad silenciosa merece atención." },
  { id: "gratitud-034", category: "gratitud", text: "Agradece a alguien un detalle concreto; la precisión puede hacer más real el reconocimiento." },
  { id: "gratitud-035", category: "gratitud", text: "Deja que el primer sorbo, la cortina abierta o el suelo fresco te recuerden que llegó la mañana." },
  { id: "gratitud-036", category: "gratitud", text: "Una habilidad cotidiana que usas sin pensar fue antes algo que tuviste que aprender." },
  { id: "gratitud-037", category: "gratitud", text: "Observa qué carga no apareció hoy; a veces una ausencia puede ser una amabilidad silenciosa." },
  { id: "gratitud-038", category: "gratitud", text: "Un objeto reparado guarda dos regalos: su utilidad y la decisión de alguien de no rendirse con él." },
  { id: "gratitud-039", category: "gratitud", text: "Presta atención a un sonido que haga que este lugar te resulte familiar." },
  { id: "gratitud-040", category: "gratitud", text: "Recuerda a quienes trabajan para que tengas calles limpias, comida segura o luz fiable." },
  { id: "gratitud-041", category: "gratitud", text: "Un plan que cambió quizá también te haya llevado a un lugar digno de atención." },
  { id: "gratitud-042", category: "gratitud", text: "Guarda un detalle pequeño de hoy antes de que los grandes hechos ocupen toda la historia." },
  { id: "gratitud-043", category: "gratitud", text: "Agradece la pregunta que te hizo pensar, aunque la respuesta todavía se esté formando." },
  { id: "gratitud-044", category: "gratitud", text: "La oportunidad de intentarlo de nuevo puede parecer corriente hasta que recuerdas que no estaba asegurada." },
  { id: "gratitud-045", category: "gratitud", text: "Observa qué facilitaron hoy tus manos, desde atarte un zapato hasta preparar una comida." },
  { id: "gratitud-046", category: "gratitud", text: "Una broma compartida puede ser un refugio breve; disfrútala sin pedirle que resuelva nada." },
  { id: "gratitud-047", category: "gratitud", text: "Puede haber cuidado en un recordatorio, una bolsa preparada o una puerta que alguien mantiene abierta para ti." },
  { id: "gratitud-048", category: "gratitud", text: "Valora el día corriente que te dio espacio suficiente para respirar, trabajar y volver a casa." },
  { id: "gratitud-049", category: "gratitud", text: "Algo que antes practicaste con cuidado quizá hoy te ayude sin pedir atención." },
  { id: "gratitud-050", category: "gratitud", text: "Deja que una canción conocida te devuelva a un buen momento que casi habías extraviado." },
  { id: "gratitud-051", category: "gratitud", text: "Agradece al amigo que envía ese mensaje cotidiano que mantiene vivo el hilo entre los dos." },
  { id: "gratitud-052", category: "gratitud", text: "Un error útil puede dejarte mejores preguntas que un éxito fácil." },
  { id: "gratitud-053", category: "gratitud", text: "Observa la sombra en una calle calurosa, el banco en un paseo largo, la pausa cuando la necesitabas." },
  { id: "gratitud-054", category: "gratitud", text: "Conserva un objeto que te recuerde hasta dónde te ha llevado un esfuerzo cotidiano." },
  { id: "gratitud-055", category: "gratitud", text: "Una comida puede contener clima, trabajo, memoria y cuidado antes de llegar al plato." },
  { id: "gratitud-056", category: "gratitud", text: "Agradece que un problema haya resultado ser más pequeño de lo que temías." },
  { id: "gratitud-057", category: "gratitud", text: "Cuando alguien recuerde un detalle sobre ti, observa la atención que lo hizo posible." },
  { id: "gratitud-058", category: "gratitud", text: "La posibilidad de empezar de nuevo esta mañana merece atención antes de que mande el horario." },
  { id: "gratitud-059", category: "gratitud", text: "Busca el relevo inadvertido que ayudó a que tu día continuara sin tropiezos." },
  { id: "gratitud-060", category: "gratitud", text: "Antes de dormir, elige un momento que agradecerías reconocer si mañana se pareciera a hoy." },
  { id: "valentia-001", category: "valentia", text: "La valentía no es no temblar; es avanzar sin entregarle el volante al miedo." },
  { id: "valentia-002", category: "valentia", text: "Elige una acción segura y preparada que dé al miedo algo real a lo que responder." },
  { id: "valentia-003", category: "valentia", text: "No necesitas certeza absoluta para tomar una decisión honesta." },
  { id: "valentia-004", category: "valentia", text: "Lo que evitas también ocupa espacio; míralo de frente." },
  { id: "valentia-005", category: "valentia", text: "Atrévete a decepcionar expectativas que te estaban apagando." },
  { id: "valentia-006", category: "valentia", text: "La valentía también puede ser una decisión privada que nadie llega a aplaudir." },
  { id: "valentia-007", category: "valentia", text: "El miedo puede alzar la voz ante una decisión importante; escúchalo y decide después qué es seguro y fiel a ti." },
  { id: "valentia-008", category: "valentia", text: "No confundas prudencia con esconderte para siempre." },
  { id: "valentia-009", category: "valentia", text: "Prueba una parte manejable de lo que antes parecía demasiado grande y aprende de lo que ocurra." },
  { id: "valentia-010", category: "valentia", text: "Tu voz puede temblar y aun así decir la verdad." },
  { id: "valentia-011", category: "valentia", text: "Elegirte puede dar miedo; da el paso cuando también respete tu seguridad y tus valores." },
  { id: "valentia-012", category: "valentia", text: "A veces crecer es dejar de negociar con lo que te encoge." },
  { id: "valentia-013", category: "valentia", text: "No toda incertidumbre es una advertencia; a veces solo es el borde de algo nuevo." },
  { id: "valentia-014", category: "valentia", text: "Antes de que la tarea crezca en tu imaginación, define y prepara un primer paso seguro." },
  { id: "valentia-015", category: "valentia", text: "La valentía empieza cuando decides no vivir solo para evitar incomodidad." },
  { id: "valentia-016", category: "valentia", text: "La valentía puede ser silenciosa: quedarte donde la verdad necesita una voz." },
  { id: "valentia-017", category: "valentia", text: "Puedes escuchar al miedo sin dejar que tome cada decisión; comprueba los hechos y elige con cuidado." },
  { id: "valentia-018", category: "valentia", text: "Un siguiente paso honesto puede incomodar; examina sus consecuencias y elige con cuidado." },
  { id: "valentia-019", category: "valentia", text: "Cada límite que expresas deja más claro qué aceptas y qué no." },
  { id: "valentia-020", category: "valentia", text: "A veces ser valiente es hacer la pregunta cuya respuesta podría cambiar tus planes." },
  { id: "valentia-021", category: "valentia", text: "Puedes entrar en lo desconocido sin fingir que no tienes miedo." },
  { id: "valentia-022", category: "valentia", text: "Hay puertas que solo se abren cuando aceptas no conocer la habitación siguiente." },
  { id: "valentia-023", category: "valentia", text: "Decir «me equivoqué» puede exigir más fuerza que seguir defendiéndote." },
  { id: "valentia-024", category: "valentia", text: "Cuando una elección importa, esperar indefinidamente también elige por ti." },
  { id: "valentia-025", category: "valentia", text: "Deja que empiecen tus manos nerviosas; la confianza puede alcanzarlas después." },
  { id: "valentia-026", category: "valentia", text: "Proteger lo que importa a veces exige soportar que no te entiendan durante un tiempo." },
  { id: "valentia-027", category: "valentia", text: "Puedes explorar lo que viene antes de dejar lo conocido; el valor también permite una transición prudente." },
  { id: "valentia-028", category: "valentia", text: "Si la situación es segura, la valentía puede ser quedarte para aprender en vez de huir ante la primera incomodidad." },
  { id: "valentia-029", category: "valentia", text: "Nombra con claridad lo que te duele; la vaguedad deja demasiado espacio al miedo." },
  { id: "valentia-030", category: "valentia", text: "Una verdad difícil se vuelve más habitable cuando por fin encuentra una voz." },
  { id: "valentia-031", category: "valentia", text: "La valentía puede empezar leyendo despacio el mensaje difícil en vez de imaginar su contenido." },
  { id: "valentia-032", category: "valentia", text: "Pide la aclaración que necesitas antes de que la incertidumbre escriba la historia por ti." },
  { id: "valentia-033", category: "valentia", text: "Prepárate con cuidado y deja que esa preparación sostenga el paso en vez de aplazarlo." },
  { id: "valentia-034", category: "valentia", text: "Admitir que necesitas tiempo puede ser más valiente que dar una respuesta en la que no confías." },
  { id: "valentia-035", category: "valentia", text: "Pide la cita que convierta una preocupación privada en algo que puedas examinar con claridad." },
  { id: "valentia-036", category: "valentia", text: "Una retirada prudente puede proteger lo importante; ser valiente no impide reconsiderar." },
  { id: "valentia-037", category: "valentia", text: "Nombra la condición que necesitarías para intentarlo y empieza a construirla." },
  { id: "valentia-038", category: "valentia", text: "Deja que tu primera pregunta sea imperfecta; una conversación real necesita un comienzo." },
  { id: "valentia-039", category: "valentia", text: "Lleva a alguien de confianza cuando el paso importante resulte demasiado pesado para darlo a solas." },
  { id: "valentia-040", category: "valentia", text: "Aclara los hechos cuando callar dejaría a alguien con una versión falsa de ti." },
  { id: "valentia-041", category: "valentia", text: "Un plan valiente incluye una salida, un teléfono y suficiente información para elegir con seguridad." },
  { id: "valentia-042", category: "valentia", text: "Di primero la verdad más pequeña si eso te ayuda a encontrar palabras para la más grande." },
  { id: "valentia-043", category: "valentia", text: "Reconsidera la oportunidad ignorada separando los costes comprobados de las preguntas abiertas." },
  { id: "valentia-044", category: "valentia", text: "Pregunta qué puedes probar a pequeña escala antes de tratar la elección como irreversible." },
  { id: "valentia-045", category: "valentia", text: "Deja que la pausa antes de hablar reúna tu sinceridad en vez de enterrarla." },
  { id: "valentia-046", category: "valentia", text: "Cambiar de rumbo ante nuevas pruebas es un acto responsable, no una falta de valor." },
  { id: "valentia-047", category: "valentia", text: "Entra en la sala sabiendo que puedes escuchar, preguntar y decidir más tarde." },
  { id: "valentia-048", category: "valentia", text: "Prométete hablar cuando el momento tenga la calma necesaria para que se escuche la verdad." },
  { id: "valentia-049", category: "valentia", text: "Ser el primero en suavizar el tono no exige renunciar a tu argumento." },
  { id: "valentia-050", category: "valentia", text: "El riesgo merece estudio; el valor informado deja menos decisiones en manos del pánico." },
  { id: "valentia-051", category: "valentia", text: "Enseña el primer borrador a una persona sensata en vez de ocultárselo a todo el mundo." },
  { id: "valentia-052", category: "valentia", text: "El siguiente paso puede ser documentar lo ocurrido antes de decidir cómo responder." },
  { id: "valentia-053", category: "valentia", text: "Pide directamente lo que necesitas y deja a la otra persona libertad para responder con sinceridad." },
  { id: "valentia-054", category: "valentia", text: "Empieza la conversación con lo que observaste, no con el veredicto que preparó el miedo." },
  { id: "valentia-055", category: "valentia", text: "Deja espacio para la sorpresa; no todo encuentro difícil repite el antiguo guion." },
  { id: "valentia-056", category: "valentia", text: "Si el lugar no parece seguro, elegir distancia puede ser la decisión valiente." },
  { id: "valentia-057", category: "valentia", text: "Escribe primero la pregunta; las palabras escritas pueden ayudar al valor a tomar forma." },
  { id: "valentia-058", category: "valentia", text: "Asume tu parte sin ofrecerte a cargar con lo que corresponde a los demás." },
  { id: "valentia-059", category: "valentia", text: "Empieza antes de sentirte brillante; la sinceridad basta para un primer intento." },
  { id: "valentia-060", category: "valentia", text: "Después del paso difícil, date tiempo para calmarte antes de juzgar cómo lo afrontaste." },
  { id: "habitos-001", category: "habitos", text: "Un hábito bueno no necesita impresionar; necesita repetirse." },
  { id: "habitos-002", category: "habitos", text: "Reduce el esfuerzo de preparación hasta que empezar sea claro y deja que la rutina crezca solo si encaja." },
  { id: "habitos-003", category: "habitos", text: "Una rutina práctica puede mantener disponible una acción útil en los días en que cambie la motivación." },
  { id: "habitos-004", category: "habitos", text: "No construyas desde la culpa; construye desde una versión más amable de orden." },
  { id: "habitos-005", category: "habitos", text: "El hábito empieza cuando dejas de decidirlo cada día." },
  { id: "habitos-006", category: "habitos", text: "Una repetición pequeña puede ser el principio de una identidad nueva." },
  { id: "habitos-007", category: "habitos", text: "Lo que preparas por la noche te cuida por la mañana." },
  { id: "habitos-008", category: "habitos", text: "Mantén el material en buen estado; una pequeña reparación puede proteger la rutina de mañana." },
  { id: "habitos-009", category: "habitos", text: "Volver al hábito después de fallar también forma parte del hábito." },
  { id: "habitos-010", category: "habitos", text: "Cuando las elecciones útiles exigen menos negociación, queda atención para el resto del día." },
  { id: "habitos-011", category: "habitos", text: "Empieza con una acción breve y completa que deje un punto claro para continuar mañana." },
  { id: "habitos-012", category: "habitos", text: "Quita un paso innecesario de la rutina y observa si volver resulta más fácil." },
  { id: "habitos-013", category: "habitos", text: "Un sistema útil hace más fácil comenzar y menos costoso volver después de fallar." },
  { id: "habitos-014", category: "habitos", text: "No necesitas cambiar toda tu vida; empieza cambiando el primer gesto del día." },
  { id: "habitos-015", category: "habitos", text: "La constancia se diseña mejor de lo que se fuerza." },
  { id: "habitos-016", category: "habitos", text: "Una rutina útil deja sitio a los días malos en vez de derrumbarse con ellos." },
  { id: "habitos-017", category: "habitos", text: "Deja el primer paso donde tu versión cansada pueda encontrarlo sin pensar demasiado." },
  { id: "habitos-018", category: "habitos", text: "Mide cuánto tardas en volver, no cuántos días lograste ser impecable." },
  { id: "habitos-019", category: "habitos", text: "Un entorno bien preparado facilita la elección que te ayuda cuando estás cansado." },
  { id: "habitos-020", category: "habitos", text: "Vincula la acción a una señal estable y recordarla requerirá menos esfuerzo." },
  { id: "habitos-021", category: "habitos", text: "Si un hábito solo funciona cuando estás inspirado, todavía necesita una base más firme." },
  { id: "habitos-022", category: "habitos", text: "Deja una señal visible de lo que cumpliste; el progreso también necesita memoria." },
  { id: "habitos-023", category: "habitos", text: "Termina el día de una forma que le facilite el comienzo a tu yo de mañana." },
  { id: "habitos-024", category: "habitos", text: "Protege una versión mínima del hábito para los días en que no puedas dar más." },
  { id: "habitos-025", category: "habitos", text: "Los hábitos se vuelven más sostenibles cuando el descanso forma parte del diseño." },
  { id: "habitos-026", category: "habitos", text: "Cuenta a alguien de confianza qué quieres repetir y pide ánimo en vez de vigilancia." },
  { id: "habitos-027", category: "habitos", text: "Saltarte una vez es un hecho; volver en la siguiente ocasión es una decisión." },
  { id: "habitos-028", category: "habitos", text: "Mejora el camino del hábito antes de culparte por no recorrerlo mejor." },
  { id: "habitos-029", category: "habitos", text: "El ritmo adecuado no solo funciona en semanas perfectas; también sobrevive a las ocupadas." },
  { id: "habitos-030", category: "habitos", text: "Elige una rutina que puedas pausar, retomar y seguir ajustando." },
  { id: "habitos-031", category: "habitos", text: "Deja el libro sobre la silla esta noche para que la primera página de mañana ya tenga una invitación." },
  { id: "habitos-032", category: "habitos", text: "Anota la versión más pequeña de la rutina antes de que un día ocupado la decida por ti." },
  { id: "habitos-033", category: "habitos", text: "Un punto final claro facilita volver mañana más que trabajar hasta quedarte sin energía." },
  { id: "habitos-034", category: "habitos", text: "Mantén las herramientas del hábito útil más cerca que las distracciones que compiten con él." },
  { id: "habitos-035", category: "habitos", text: "Elige una señal que ya notes: la cafetera, el trayecto o el momento de cerrar el portátil." },
  { id: "habitos-036", category: "habitos", text: "Registra la acción hasta entender su patrón y conserva después solo el control que te ayude." },
  { id: "habitos-037", category: "habitos", text: "Prepárate para el obstáculo previsible antes de pedir otra vez a la fuerza de voluntad que lo resuelva." },
  { id: "habitos-038", category: "habitos", text: "Una rutina de quince minutos necesita un lugar real en el calendario, no una intención imprecisa." },
  { id: "habitos-039", category: "habitos", text: "Acorta la distancia entre decidir y empezar: abre el archivo, llena la botella, prepara los zapatos." },
  { id: "habitos-040", category: "habitos", text: "Revisa la semana sin puntuar tu carácter; ajustas un sistema, no juzgas a una persona." },
  { id: "habitos-041", category: "habitos", text: "Si la rutina falla siempre a la misma hora, cambia la hora antes de aumentar el esfuerzo." },
  { id: "habitos-042", category: "habitos", text: "Une la tarea que aplazas a un comienzo agradable, como música o un lugar que te guste." },
  { id: "habitos-043", category: "habitos", text: "Cuando pares a mitad, deja los materiales en el orden en que los necesitarás después." },
  { id: "habitos-044", category: "habitos", text: "Un hábito puede reducirse durante una semana difícil sin desaparecer de tu vida." },
  { id: "habitos-045", category: "habitos", text: "Cambia el lugar o el formato cuando sea el aburrimiento, y no la dificultad, lo que interrumpe la rutina." },
  { id: "habitos-046", category: "habitos", text: "Guarda cada objeto donde empieza la acción, no donde la habitación resulte más vistosa." },
  { id: "habitos-047", category: "habitos", text: "Cuando dos hábitos compitan, protege el que facilite el otro mañana." },
  { id: "habitos-048", category: "habitos", text: "Usa recordatorios como puente mientras la rutina sea nueva y retira los que se conviertan en ruido." },
  { id: "habitos-049", category: "habitos", text: "Haz concreto el reinicio: nombra el día, el lugar y la primera acción visible." },
  { id: "habitos-050", category: "habitos", text: "Un calendario visible puede revelar si el plan respeta la vida que realmente tienes." },
  { id: "habitos-051", category: "habitos", text: "Coloca un pequeño placer cerca del final para que la rutina termine con una razón para volver." },
  { id: "habitos-052", category: "habitos", text: "Antes de añadir una rutina, decide qué antigua exigencia le dejará espacio." },
  { id: "habitos-053", category: "habitos", text: "Un hábito que cabe en un día exigente tiene más opciones de durar durante un mes ajetreado." },
  { id: "habitos-054", category: "habitos", text: "Usa un día perdido para revisar el sistema, no para repetir un discurso sobre disciplina." },
  { id: "habitos-055", category: "habitos", text: "Una comida lista, una mesa despejada o un paseo agendado pueden facilitar una elección útil." },
  { id: "habitos-056", category: "habitos", text: "Deja que la rutina termine pronto alguna vez; acabar con energía puede proteger el próximo regreso." },
  { id: "habitos-057", category: "habitos", text: "Nombra la fricción con precisión: tiempo, herramientas, lugar, energía o un primer paso confuso." },
  { id: "habitos-058", category: "habitos", text: "Un reinicio semanal puede ser diez minutos tranquilos devolviendo lo útil a su sitio." },
  { id: "habitos-059", category: "habitos", text: "Si el plan depende de recordarlo, coloca el aviso donde la decisión ocurre de verdad." },
  { id: "habitos-060", category: "habitos", text: "Elige la próxima repetición antes de celebrar esta; la continuidad agradece una invitación clara." },
  { id: "creatividad-001", category: "creatividad", text: "La idea no llega siempre brillante; a veces llega torpe y pide que la cuides." },
  { id: "creatividad-002", category: "creatividad", text: "Crea antes de juzgar: el editor puede esperar a que exista algo." },
  { id: "creatividad-003", category: "creatividad", text: "Deja sitio para las ideas repentinas, pero concede a las más discretas el tiempo necesario para crecer." },
  { id: "creatividad-004", category: "creatividad", text: "No busques ser original a la fuerza; busca ser honesto con precisión." },
  { id: "creatividad-005", category: "creatividad", text: "Una mala primera versión es una puerta, no una sentencia." },
  { id: "creatividad-006", category: "creatividad", text: "La creatividad necesita juego, pero también necesita terminar algo." },
  { id: "creatividad-007", category: "creatividad", text: "Mira lo conocido desde otro ángulo y ya tendrás material." },
  { id: "creatividad-008", category: "creatividad", text: "No todo lo que haces tiene que gustar a todos para merecer existir." },
  { id: "creatividad-009", category: "creatividad", text: "La claridad creativa aparece trabajando, no esperando una señal perfecta." },
  { id: "creatividad-010", category: "creatividad", text: "Haz una versión pequeña de la idea antes de discutirla con el miedo." },
  { id: "creatividad-011", category: "creatividad", text: "Tu voz se afina usándola, no comparándola." },
  { id: "creatividad-012", category: "creatividad", text: "Sigue una pregunta un poco más lejos de lo razonable; allí suelen aparecer ideas nuevas." },
  { id: "creatividad-013", category: "creatividad", text: "Deja que algo sea simple si así se vuelve verdadero." },
  { id: "creatividad-014", category: "creatividad", text: "La página vacía pierde poder cuando pones una frase imperfecta." },
  { id: "creatividad-015", category: "creatividad", text: "Crear también es confiar en que podrás mejorar lo que hoy apenas nace." },
  { id: "creatividad-016", category: "creatividad", text: "Haz mejores preguntas; el trabajo interesante suele empezar donde falla la respuesta obvia." },
  { id: "creatividad-017", category: "creatividad", text: "Guarda los fragmentos extraños; no todas las ideas llegan con instrucciones." },
  { id: "creatividad-018", category: "creatividad", text: "A veces el bloqueo creativo es exceso de ruido; despeja un rincón y vuelve a mirar." },
  { id: "creatividad-019", category: "creatividad", text: "Termina un boceto para descubrir qué estaba intentando decir realmente la idea." },
  { id: "creatividad-020", category: "creatividad", text: "Toma prestada una estructura, no una voz; las influencias pueden ser andamios." },
  { id: "creatividad-021", category: "creatividad", text: "Una limitación bien elegida puede darle al proyecto la forma que la libertad no encontraba." },
  { id: "creatividad-022", category: "creatividad", text: "Deja que la curiosidad avance unos pasos antes de exigirle que sea útil." },
  { id: "creatividad-023", category: "creatividad", text: "Observa lo que te irrita; puede estar señalando una pregunta que aún no terminaste." },
  { id: "creatividad-024", category: "creatividad", text: "Una obra que sorprende a quien la crea tiene alguna posibilidad de sorprender a otros." },
  { id: "creatividad-025", category: "creatividad", text: "Si la idea se atasca, cambia de herramienta; otra forma puede mostrarte lo que faltaba." },
  { id: "creatividad-026", category: "creatividad", text: "Protege el trabajo temprano de una audiencia prematura; primero necesita aprender a sostenerse." },
  { id: "creatividad-027", category: "creatividad", text: "La originalidad aparece al unir observaciones corrientes que solo tú habías reunido." },
  { id: "creatividad-028", category: "creatividad", text: "Hazle espacio al aburrimiento; una mente sin instrucciones empieza a buscar caminos propios." },
  { id: "creatividad-029", category: "creatividad", text: "Cada elección cierra posibilidades, y así es precisamente como una obra adquiere forma." },
  { id: "creatividad-030", category: "creatividad", text: "Deja de pulir la frase que el proyecto ya no necesita y escucha lo que pide ahora." },
  { id: "creatividad-031", category: "creatividad", text: "Una idea a medio hacer puede volverse útil cuando le das una forma en la que otra persona pueda entrar." },
  { id: "creatividad-032", category: "creatividad", text: "Guarda ese detalle que te llama la atención; ya descubrirás más adelante para qué sirve." },
  { id: "creatividad-033", category: "creatividad", text: "Empieza por esa tensión que todavía no sabes explicar; quizá sea la parte más viva de la obra." },
  { id: "creatividad-034", category: "creatividad", text: "Una rutina creativa sencilla evita que tu atención tenga que negociar con cada estado de ánimo." },
  { id: "creatividad-035", category: "creatividad", text: "Lee el borrador en voz alta; el oído puede detectar lo que tus ojos ya pasaban por alto." },
  { id: "creatividad-036", category: "creatividad", text: "Un detalle preciso puede transmitir más emoción que un párrafo lleno de adjetivos brillantes." },
  { id: "creatividad-037", category: "creatividad", text: "Termina una obra antes de convertirla en un veredicto sobre tu talento." },
  { id: "creatividad-038", category: "creatividad", text: "Cuestiona la regla que todos dejaron de ver; debajo puede esconderse un camino nuevo." },
  { id: "creatividad-039", category: "creatividad", text: "Primero reúne sin miedo y después elige con firmeza; descubrir y orientar necesitan momentos distintos." },
  { id: "creatividad-040", category: "creatividad", text: "Alterna entre hacer y observar; la distancia revela lo que el esfuerzo a veces oculta." },
  { id: "creatividad-041", category: "creatividad", text: "La parte que se resiste quizá esté señalando una decisión que el proyecto aún necesita." },
  { id: "creatividad-042", category: "creatividad", text: "Deja una pregunta abierta el tiempo suficiente para que la obra responda en su propio idioma." },
  { id: "creatividad-043", category: "creatividad", text: "Un experimento que falla con claridad también enseña cómo quiere comportarse el material." },
  { id: "creatividad-044", category: "creatividad", text: "Cambia una cosa de tu entorno y observa qué pensamientos se vuelven más accesibles." },
  { id: "creatividad-045", category: "creatividad", text: "Si una parte hermosa debilita el conjunto, guárdala aparte y deja que la obra respire." },
  { id: "creatividad-046", category: "creatividad", text: "Un título provisional puede servir de brújula sin convertirse en el destino final." },
  { id: "creatividad-047", category: "creatividad", text: "Una historia cobra vida cuando cada decisión importante cambia lo que puede ocurrir después." },
  { id: "creatividad-048", category: "creatividad", text: "La precisión es una forma discreta de valentía: permite que la obra se deje ver de verdad." },
  { id: "creatividad-049", category: "creatividad", text: "Piensa en una persona atenta ante la obra; tener un destinatario claro puede afinar tus decisiones." },
  { id: "creatividad-050", category: "creatividad", text: "Ponle un límite a la investigación para que aprender termine convirtiéndose en crear." },
  { id: "creatividad-051", category: "creatividad", text: "Cuando la mente rodea siempre la misma respuesta, un paseo puede cambiar la forma de la pregunta." },
  { id: "creatividad-052", category: "creatividad", text: "Ten cerca las herramientas para empezar y un impulso pequeño podrá convertirse en un intento real." },
  { id: "creatividad-053", category: "creatividad", text: "Antes de rechazar lo que te resulta extraño, pregúntate si está mal o si solo es nuevo para ti." },
  { id: "creatividad-054", category: "creatividad", text: "Una imagen que regresa puede ser el hilo que conecte piezas que parecían separadas." },
  { id: "creatividad-055", category: "creatividad", text: "Nombra el problema con palabras sencillas; el misterio se explora mejor cuando la confusión tiene límites." },
  { id: "creatividad-056", category: "creatividad", text: "Elige lo que haga que la obra sea más ella misma, aunque por eso resulte menos familiar." },
  { id: "creatividad-057", category: "creatividad", text: "La falta de un recurso puede provocar una solución que la abundancia nunca habría sugerido." },
  { id: "creatividad-058", category: "creatividad", text: "Deja que el borrador sea discreto cuando eso resulte sincero; no toda obra necesita anunciar su importancia." },
  { id: "creatividad-059", category: "creatividad", text: "Revisar puede aclarar el camino sin eliminar todas las sorpresas del recorrido." },
  { id: "creatividad-060", category: "creatividad", text: "Termina la sesión dejando visible el siguiente movimiento; mañana tendrás por dónde empezar." },
  { id: "resiliencia-001", category: "resiliencia", text: "No todo lo que te rompe decide cómo vas a reconstruirte." },
  { id: "resiliencia-002", category: "resiliencia", text: "Sobrevivir a un día difícil también es una forma de avance." },
  { id: "resiliencia-003", category: "resiliencia", text: "La fuerza no siempre se nota; a veces solo consiste en seguir cuidándote." },
  { id: "resiliencia-004", category: "resiliencia", text: "El cansancio puede cambiar lo razonable para hoy sin decidir lo que será posible más adelante." },
  { id: "resiliencia-005", category: "resiliencia", text: "Lo que pasó forma parte de tu historia, no tiene por qué ser tu frontera." },
  { id: "resiliencia-006", category: "resiliencia", text: "Recuperarte no exige volver igual; quizá signifique volver con una idea más clara de quién eres." },
  { id: "resiliencia-007", category: "resiliencia", text: "Lo que hoy ocupa toda tu vista no necesariamente ocupará todo tu futuro." },
  { id: "resiliencia-008", category: "resiliencia", text: "La esperanza a veces es práctica: comer, dormir, pedir ayuda, intentarlo mañana." },
  { id: "resiliencia-009", category: "resiliencia", text: "No minimices lo que cargaste solo porque aprendiste a caminar con ello." },
  { id: "resiliencia-010", category: "resiliencia", text: "Cada vez que vuelves a levantarte, negocias menos con la derrota." },
  { id: "resiliencia-011", category: "resiliencia", text: "También hay dignidad en ir recomponiéndote despacio." },
  { id: "resiliencia-012", category: "resiliencia", text: "No tienes que convertir el dolor en lección antes de permitirte sentirlo." },
  { id: "resiliencia-013", category: "resiliencia", text: "Lo difícil no te hizo menos; te mostró qué partes necesitan ternura." },
  { id: "resiliencia-014", category: "resiliencia", text: "Si hoy solo puedes sostenerte, eso también cuenta." },
  { id: "resiliencia-015", category: "resiliencia", text: "Volver a confiar en la vida puede empezar con un gesto pequeño." },
  { id: "resiliencia-016", category: "resiliencia", text: "Da tiempo a un cambio difícil para volverse familiar antes de decidir todo lo que te ha quitado." },
  { id: "resiliencia-017", category: "resiliencia", text: "Un día difícil después de una buena semana no borra todo lo que esa semana te dio." },
  { id: "resiliencia-018", category: "resiliencia", text: "Descansar puede formar parte de la reparación sin convertirse en una retirada." },
  { id: "resiliencia-019", category: "resiliencia", text: "Lo que antes te sostuvo quizá necesite cambiar; resistir también es renovar las herramientas." },
  { id: "resiliencia-020", category: "resiliencia", text: "Pide compañía antes de convertir el peso que llevas en una prueba de fortaleza." },
  { id: "resiliencia-021", category: "resiliencia", text: "Puedes llorar lo que perdiste sin perder también el interés por lo que permanece." },
  { id: "resiliencia-022", category: "resiliencia", text: "Un recuerdo difícil puede seguir en tu historia sin ocupar todo el espacio." },
  { id: "resiliencia-023", category: "resiliencia", text: "No necesitas agradecer la herida para sentir orgullo por cómo te has cuidado." },
  { id: "resiliencia-024", category: "resiliencia", text: "En algunas etapas, progresar consiste en mantener a salvo lo esencial." },
  { id: "resiliencia-025", category: "resiliencia", text: "La fortaleza puede ser cambiar el ritmo antes de que el cuerpo te obligue a parar." },
  { id: "resiliencia-026", category: "resiliencia", text: "Sobreviviste no porque nada te afectara, sino porque seguiste aprendiendo a adaptarte." },
  { id: "resiliencia-027", category: "resiliencia", text: "Cuando vuelva un dolor antiguo, recíbelo con los recursos que hoy sí tienes." },
  { id: "resiliencia-028", category: "resiliencia", text: "Un tropiezo aporta información sobre el terreno, no un veredicto sobre tu destino." },
  { id: "resiliencia-029", category: "resiliencia", text: "Empieza otra vez desde donde estás, no desde donde crees que ya deberías estar." },
  { id: "resiliencia-030", category: "resiliencia", text: "La vida que reconstruyas no tiene que parecerse a la anterior para seguir siendo tuya." },
  { id: "resiliencia-031", category: "resiliencia", text: "Un plan puede doblarse sin fracasar; ajústalo al terreno que de verdad tienes delante." },
  { id: "resiliencia-032", category: "resiliencia", text: "Cuando todo se haga pesado, protege la parte más pequeña que todavía permita avanzar." },
  { id: "resiliencia-033", category: "resiliencia", text: "No necesitas recuperar tu antigua manera de ser fuerte para recorrer la siguiente etapa." },
  { id: "resiliencia-034", category: "resiliencia", text: "Cumple una promesa cotidiana contigo; la estabilidad suele regresar por puertas conocidas." },
  { id: "resiliencia-035", category: "resiliencia", text: "Una ruta distinta puede llevarte hacia lo importante, aunque el mapa ya no sea el mismo." },
  { id: "resiliencia-036", category: "resiliencia", text: "Permite que un tropiezo cambie tu método, pero no que decida cuánto vales." },
  { id: "resiliencia-037", category: "resiliencia", text: "Aceptar una mano firme no borra ninguno de los pasos que has dado por ti." },
  { id: "resiliencia-038", category: "resiliencia", text: "Cuenta también lo que protegiste durante la etapa difícil, no solo lo que quedó sin terminar." },
  { id: "resiliencia-039", category: "resiliencia", text: "Reducir la carga de hoy no exige rebajar lo que esperas del futuro." },
  { id: "resiliencia-040", category: "resiliencia", text: "El siguiente paso útil puede ser menor de lo que quiere tu orgullo y más sensato de lo que imagina." },
  { id: "resiliencia-041", category: "resiliencia", text: "Fíjate en las opciones que aún conservas; incluso un camino estrecho puede ofrecer más de una dirección." },
  { id: "resiliencia-042", category: "resiliencia", text: "Haz de la paciencia algo activo: prepárate, observa y avanza cuando el terreno esté listo." },
  { id: "resiliencia-043", category: "resiliencia", text: "Lo aprendido bajo presión puede seguir siendo útil sin obligarte a vivir siempre bajo tensión." },
  { id: "resiliencia-044", category: "resiliencia", text: "Haz sitio para una hora buena dentro de una semana difícil; ninguna experiencia anula la otra." },
  { id: "resiliencia-045", category: "resiliencia", text: "No hay vergüenza en reconstruir con materiales más sencillos de los que imaginabas." },
  { id: "resiliencia-046", category: "resiliencia", text: "Cuando no haya certezas, elige la acción que te deje más opciones para después." },
  { id: "resiliencia-047", category: "resiliencia", text: "Un límite puede proteger la parte de ti que todavía está aprendiendo a confiar de nuevo." },
  { id: "resiliencia-048", category: "resiliencia", text: "No midas una recuperación discreta con el ritmo del éxito visible de otra persona." },
  { id: "resiliencia-049", category: "resiliencia", text: "Unos días crean impulso y otros mantienen la puerta abierta. Ambos pueden ayudarte a seguir." },
  { id: "resiliencia-050", category: "resiliencia", text: "Llévate la sabiduría, pero no todas las defensas que un día te ayudaron a resistir." },
  { id: "resiliencia-051", category: "resiliencia", text: "Puedes resolver el problema de hoy sin tener que resolver al mismo tiempo todas sus versiones futuras." },
  { id: "resiliencia-052", category: "resiliencia", text: "Una pausa consciente puede evitar que un momento difícil decida tus próximos movimientos." },
  { id: "resiliencia-053", category: "resiliencia", text: "Observa qué pequeñas decisiones evitaron que el día fuera más difícil; la resiliencia suele actuar en silencio." },
  { id: "resiliencia-054", category: "resiliencia", text: "Echar de menos lo conocido no impide elegir algo más acorde con el futuro que quieres." },
  { id: "resiliencia-055", category: "resiliencia", text: "Cuando cueste ver el progreso, compara tus decisiones de ahora con las que podías tomar antes." },
  { id: "resiliencia-056", category: "resiliencia", text: "Repara un rincón que tengas a tu alcance; el orden no necesita volver a todas partes a la vez." },
  { id: "resiliencia-057", category: "resiliencia", text: "Tu ritmo puede cambiar con las circunstancias sin apartarte de la dirección que valoras." },
  { id: "resiliencia-058", category: "resiliencia", text: "Deja en el plan un poco de espacio para ser humano; resistir también exige expectativas honestas." },
  { id: "resiliencia-059", category: "resiliencia", text: "Un capítulo difícil también merece un final amable antes de que empiece el siguiente." },
  { id: "resiliencia-060", category: "resiliencia", text: "Reconoce lo que sigue siendo posible hoy; la claridad puede convertir una situación difícil en un punto de partida." },
  { id: "relaciones-001", category: "relaciones", text: "Escuchar bien es una forma silenciosa de decir: importas." },
  { id: "relaciones-002", category: "relaciones", text: "No confundas paz con callarte siempre." },
  { id: "relaciones-003", category: "relaciones", text: "El amor sano no exige que desaparezcas para que el otro esté cómodo." },
  { id: "relaciones-004", category: "relaciones", text: "Una conversación honesta a tiempo puede evitar que crezca una gran distancia." },
  { id: "relaciones-005", category: "relaciones", text: "Ofrece a las personas que quieres un poco de atención que no tenga que competir con una pantalla." },
  { id: "relaciones-006", category: "relaciones", text: "Un límite claro da al vínculo espacio para continuar sin acumular resentimiento en silencio." },
  { id: "relaciones-007", category: "relaciones", text: "No todo vínculo merece el mismo acceso a tu energía." },
  { id: "relaciones-008", category: "relaciones", text: "Agradece a quien hace fácil ser tú." },
  { id: "relaciones-009", category: "relaciones", text: "La cercanía se construye con detalles repetidos, no con gestos enormes aislados." },
  { id: "relaciones-010", category: "relaciones", text: "Puedes querer a alguien y aun así necesitar espacio." },
  { id: "relaciones-011", category: "relaciones", text: "La intensidad y la cercanía no son lo mismo; observa si el vínculo también deja espacio para la estabilidad." },
  { id: "relaciones-012", category: "relaciones", text: "La confianza crece donde las palabras y los hechos se parecen." },
  { id: "relaciones-013", category: "relaciones", text: "Cuida tus vínculos, pero no uses tu paz como moneda." },
  { id: "relaciones-014", category: "relaciones", text: "Haz sitio para quienes te permiten descansar sin pedirte que seas otra persona." },
  { id: "relaciones-015", category: "relaciones", text: "Una disculpa real no busca ganar; busca reparar." },
  { id: "relaciones-016", category: "relaciones", text: "Ser comprendido empieza por arriesgarte a decir lo que realmente quieres decir." },
  { id: "relaciones-017", category: "relaciones", text: "Cuidar bien también exige interesarse por quién es hoy la otra persona, no solo recordar quién fue." },
  { id: "relaciones-018", category: "relaciones", text: "Un vínculo sano puede sostener las diferencias sin convertirlas en amenazas." },
  { id: "relaciones-019", category: "relaciones", text: "Pregunta antes de suponer; la imaginación sustituye muy mal a una conversación." },
  { id: "relaciones-020", category: "relaciones", text: "La fiabilidad es una forma de cariño que también aparece en el calendario." },
  { id: "relaciones-021", category: "relaciones", text: "Puedes ser amable sin convertirte en una persona disponible a cualquier hora." },
  { id: "relaciones-022", category: "relaciones", text: "La reparación empieza cuando el impacto importa más que defender la intención." },
  { id: "relaciones-023", category: "relaciones", text: "La amistad también necesita invitaciones concretas, no solo afecto silencioso." },
  { id: "relaciones-024", category: "relaciones", text: "Las personas cambian; querer su versión presente exige actualizar cómo las miras." },
  { id: "relaciones-025", category: "relaciones", text: "El silencio también puede ser compañía cuando nadie te obliga a llenarlo." },
  { id: "relaciones-026", category: "relaciones", text: "Un conflicto tratado con respeto puede hacer que la cercanía sea más sincera." },
  { id: "relaciones-027", category: "relaciones", text: "No pongas pruebas secretas a los demás; cuéntales con claridad qué necesitas." },
  { id: "relaciones-028", category: "relaciones", text: "La reciprocidad no tiene que ser idéntica, pero sí debe sentirse mutua." },
  { id: "relaciones-029", category: "relaciones", text: "Celebra también las victorias corrientes de quienes quieres; allí transcurre gran parte de la vida." },
  { id: "relaciones-030", category: "relaciones", text: "Dejar espacio para un «no» hace que cada «sí» dentro del vínculo sea más honesto." },
  { id: "relaciones-031", category: "relaciones", text: "Observa cómo reciben el cuidado las personas que quieres; la atención vuelve útiles las buenas intenciones." },
  { id: "relaciones-032", category: "relaciones", text: "Un mensaje breve enviado hoy evita que el cariño se quede solo en una buena intención." },
  { id: "relaciones-033", category: "relaciones", text: "Escucha la necesidad detrás de una frase torpe sin fingir que sus palabras no hicieron daño." },
  { id: "relaciones-034", category: "relaciones", text: "Dile a la gente lo que aprecias mientras el momento cotidiano todavía está ocurriendo." },
  { id: "relaciones-035", category: "relaciones", text: "La conexión crece cuando ambos pueden compartir ideas incompletas sin sentirse apurados." },
  { id: "relaciones-036", category: "relaciones", text: "Antes de resolver el problema de alguien, averigua si quiere ideas, ayuda o simplemente compañía." },
  { id: "relaciones-037", category: "relaciones", text: "Cuando cambien los planes, avisa pronto; cuidar también es respetar el tiempo que alguien reservó." },
  { id: "relaciones-038", category: "relaciones", text: "Discrepar no exige convertir el carácter de la otra persona en el tema de la discusión." },
  { id: "relaciones-039", category: "relaciones", text: "Comparte un poco de contexto; nadie puede comprender una historia que nunca le permites conocer." },
  { id: "relaciones-040", category: "relaciones", text: "Haz que el cariño sea práctico: recuerda la fecha, acerca el agua, haz la llamada." },
  { id: "relaciones-041", category: "relaciones", text: "Recordar una pequeña preferencia puede hacer que alguien se sienta tenido en cuenta, no dirigido." },
  { id: "relaciones-042", category: "relaciones", text: "No obligues a la cercanía a demostrarse con acceso constante; la confianza también necesita aire." },
  { id: "relaciones-043", category: "relaciones", text: "Cuando entiendas algo mal, vuelve primero con curiosidad y no con una defensa preparada." },
  { id: "relaciones-044", category: "relaciones", text: "Una amistad puede cambiar de forma sin perder sentido; pregunta qué manera de conectar encaja ahora." },
  { id: "relaciones-045", category: "relaciones", text: "Alguien puede cuidar de otra manera sin cuidar menos; observa sus gestos antes de sacar conclusiones." },
  { id: "relaciones-046", category: "relaciones", text: "Una verdad difícil puede decirse sin usar la dureza como prueba de sinceridad." },
  { id: "relaciones-047", category: "relaciones", text: "Fíjate en quien hace una segunda pregunta; la atención suele mostrar el cariño mejor que un consejo." },
  { id: "relaciones-048", category: "relaciones", text: "Da margen para corregir un error, pero deja que los patrones repetidos orienten tu confianza." },
  { id: "relaciones-049", category: "relaciones", text: "La cercanía es más segura cuando nadie tiene que adivinar qué reglas valen hoy." },
  { id: "relaciones-050", category: "relaciones", text: "Si la conversación importa, elige un lugar donde ninguno tenga que competir con el ruido." },
  { id: "relaciones-051", category: "relaciones", text: "Respeta la respuesta que pediste, sobre todo cuando no es la que esperabas escuchar." },
  { id: "relaciones-052", category: "relaciones", text: "Preguntar con cuidado puede decir «me acuerdo de ti» sin exigir nada a cambio." },
  { id: "relaciones-053", category: "relaciones", text: "Deja que una persona nueva te muestre quién es antes de darle un papel de tu pasado." },
  { id: "relaciones-054", category: "relaciones", text: "En un conflicto, habla con quien tienes delante, no con un público imaginario que te da la razón." },
  { id: "relaciones-055", category: "relaciones", text: "Hacer algo juntos también crea cercanía; no todo intercambio importante sucede cara a cara." },
  { id: "relaciones-056", category: "relaciones", text: "Pregunta antes de contar una historia ajena; la confianza también consiste en cuidar lo que te confiaron." },
  { id: "relaciones-057", category: "relaciones", text: "Los vínculos necesitan actualizarse; lo que ayudaba el año pasado quizá hoy requiera otra conversación." },
  { id: "relaciones-058", category: "relaciones", text: "En un grupo, fíjate en quien aún no encuentra cómo entrar en la conversación; acoger también es actuar." },
  { id: "relaciones-059", category: "relaciones", text: "Deja espacio entre la pregunta y tu respuesta; a veces la comprensión llega durante la pausa." },
  { id: "relaciones-060", category: "relaciones", text: "Un buen vínculo deja sitio para dos vidas completas, no para una girando alrededor de la otra." },
  { id: "energia-001", category: "energia", text: "No administres tu día como si tu energía fuera infinita." },
  { id: "energia-002", category: "energia", text: "Protege algo de energía antes de necesitarla; no toda reserva debe llegar a cero." },
  { id: "energia-003", category: "energia", text: "Haz primero lo que requiere lo mejor de ti, no lo que puede hacerse con la energía que te sobra." },
  { id: "energia-004", category: "energia", text: "Descansar a tiempo también es una decisión productiva." },
  { id: "energia-005", category: "energia", text: "Si todo te irrita, quizá no necesitas una respuesta; necesitas una pausa." },
  { id: "energia-006", category: "energia", text: "Observa pronto cuándo tu ritmo empieza a ser difícil de sostener y deja margen para ajustarlo." },
  { id: "energia-007", category: "energia", text: "No llenes cada hueco: el espacio libre también trabaja a tu favor." },
  { id: "energia-008", category: "energia", text: "La mañana mejora cuando no empieza con el mundo entero entrando por una pantalla." },
  { id: "energia-009", category: "energia", text: "Cuida la primera hora; suele decidir el tono de muchas más." },
  { id: "energia-010", category: "energia", text: "Menos exceso, más ritmo: así dura lo que de verdad importa." },
  { id: "energia-011", category: "energia", text: "Una agenda llena puede ocultar si alguna de sus tareas sigue importándote de verdad." },
  { id: "energia-012", category: "energia", text: "Un vaso de agua, una ventana abierta y cinco minutos pueden cambiar cómo vives el resto del día." },
  { id: "energia-013", category: "energia", text: "Si tu atención decae, observa si tu cuerpo lleva tiempo pidiendo cuidado." },
  { id: "energia-014", category: "energia", text: "Elige una cosa que te devuelva energía en vez de otra que solo la consuma." },
  { id: "energia-015", category: "energia", text: "La ambición que no descansa acaba pareciéndose al castigo." },
  { id: "energia-016", category: "energia", text: "Tu día necesita márgenes; sin ellos, cualquier imprevisto se convierte en una emergencia." },
  { id: "energia-017", category: "energia", text: "Usa tus horas más lúcidas para crear y deja las tareas rutinarias para momentos más lentos." },
  { id: "energia-018", category: "energia", text: "Antes de juzgar el día entero, cambia una condición pequeña y observa si la hora siguiente se siente distinta." },
  { id: "energia-019", category: "energia", text: "Algunos cansancios piden sueño; otros, compañía, aire nuevo o cambiar de escenario." },
  { id: "energia-020", category: "energia", text: "Detente antes de vaciarte para que mañana no tenga que pagar todo el coste." },
  { id: "energia-021", category: "energia", text: "El interés puede despertar tu energía, pero tu cuerpo sigue necesitando combustible." },
  { id: "energia-022", category: "energia", text: "Retira hoy una fuente de ruido y observa qué parte de ti vuelve a tener espacio." },
  { id: "energia-023", category: "energia", text: "Recuperarte no es el premio por llegar al límite; forma parte de un ritmo sostenible." },
  { id: "energia-024", category: "energia", text: "Observa qué conversaciones te dejan más claro y cuáles te dispersan durante horas." },
  { id: "energia-025", category: "energia", text: "Una mañana más lenta puede preparar una tarde mucho más útil." },
  { id: "energia-026", category: "energia", text: "Acerca el trabajo exigente a las horas en que tu atención despierta con naturalidad." },
  { id: "energia-027", category: "energia", text: "Las pausas funcionan mejor antes de que la concentración desaparezca por completo." },
  { id: "energia-028", category: "energia", text: "Protege la transición entre trabajar y descansar; tu mente necesita notar la diferencia." },
  { id: "energia-029", category: "energia", text: "La estimulación constante puede esconder el cansancio sin llegar a repararlo." },
  { id: "energia-030", category: "energia", text: "No gastes la energía de mañana solo para demostrar que hoy podías terminarlo todo." },
  { id: "energia-031", category: "energia", text: "Reserva en la agenda tiempo para recuperarte junto al esfuerzo; lo que no tiene lugar se aplaza con facilidad." },
  { id: "energia-032", category: "energia", text: "Una lista más corta puede proteger la atención necesaria para hacer bien lo importante." },
  { id: "energia-033", category: "energia", text: "Ajusta el entorno a la energía que pide la tarea; algunos trabajos agradecen silencio y otros, movimiento." },
  { id: "energia-034", category: "energia", text: "Reserva las decisiones fáciles para las horas lentas y guarda la mente clara para lo importante." },
  { id: "energia-035", category: "energia", text: "Quizá la tarea no necesite más fuerza, sino un punto de partida mejor elegido." },
  { id: "energia-036", category: "energia", text: "Reduce los asuntos abiertos; las decisiones pendientes reclaman atención aunque no hagan ruido." },
  { id: "energia-037", category: "energia", text: "Un ritmo que se pueda sostener incluye momentos que no tienen que producir nada." },
  { id: "energia-038", category: "energia", text: "Si el día empieza tarde, rediseña lo que queda en vez de comprimir el plan original." },
  { id: "energia-039", category: "energia", text: "Deja una parte de la noche libre del día siguiente; anticipar también puede gastar el descanso." },
  { id: "energia-040", category: "energia", text: "Agrupa los recados pequeños cuando puedas; cambiar continuamente hace que cada uno cueste más atención." },
  { id: "energia-041", category: "energia", text: "Antes de buscar motivación, elimina un obstáculo que vuelva innecesariamente costoso empezar." },
  { id: "energia-042", category: "energia", text: "Un comienzo sereno puede servir más que pedirle urgencia a una fecha que aún queda lejos." },
  { id: "energia-043", category: "energia", text: "Deja tan clara la siguiente acción que empezar no exija volver a discutirlo contigo." },
  { id: "energia-044", category: "energia", text: "Cuando un compromiso se repite, cuenta también el tiempo de preparación y recuperación, no solo la hora prevista." },
  { id: "energia-045", category: "energia", text: "No todas las horas de poca energía necesitan arreglo; algunas solo piden una tarea más amable." },
  { id: "energia-046", category: "energia", text: "Asigna un lugar fijo a las tareas recurrentes; decidir menos deja más atención disponible." },
  { id: "energia-047", category: "energia", text: "Observa qué compromisos te reaniman después del esfuerzo y cuáles solo te dejan agotado." },
  { id: "energia-048", category: "energia", text: "Protege el tiempo anterior a una tarea importante de las decisiones que pueden esperar." },
  { id: "energia-049", category: "energia", text: "Incluye el momento de parar en el plan; si no, cada tarea intentará decidir por sí sola cuándo termina." },
  { id: "energia-050", category: "energia", text: "Unos minutos de preparación pueden convertir el primer paso de mañana en una invitación más fácil." },
  { id: "energia-051", category: "energia", text: "A veces el impulso nace de quitar: una pestaña, una reunión, una promesa innecesaria." },
  { id: "energia-052", category: "energia", text: "Ajusta el esfuerzo a la importancia del resultado, no al ruido que haya a su alrededor." },
  { id: "energia-053", category: "energia", text: "Un día con una prioridad clara exige menos atención que otro con diez alarmas igual de urgentes." },
  { id: "energia-054", category: "energia", text: "Cuando todo parezca urgente, busca lo que seguiría importando si el ruido se apagara." },
  { id: "energia-055", category: "energia", text: "Protege una comida sin prisas para que no se convierta en otra pausa llena de obligaciones." },
  { id: "energia-056", category: "energia", text: "Reserva un rato sin mensajes entrantes; la atención sin interrupciones puede resultar más ligera que las prisas." },
  { id: "energia-057", category: "energia", text: "El espacio que queda al terminar te pertenece antes de pertenecer a la siguiente exigencia." },
  { id: "energia-058", category: "energia", text: "Construye un día que puedas repetir, no uno que solo parezca admirable visto desde fuera." },
  { id: "energia-059", category: "energia", text: "Observa cuándo el esfuerzo deja de mejorar el resultado; dedicar más tiempo no siempre significa cuidar más." },
  { id: "energia-060", category: "energia", text: "Permite que «es suficiente» sea a veces una elección consciente, no una disculpa por lo pendiente." },
];
